import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', hue1:0,   hue2:340, speed:0.22, distort:0.75 },
  { score:2, emoji:'😟', label:'Dåligt',         hue1:18,  hue2:350, speed:0.30, distort:0.58 },
  { score:3, emoji:'😐', label:'Okej',           hue1:42,  hue2:28,  speed:0.42, distort:0.42 },
  { score:4, emoji:'🙂', label:'Bra',            hue1:158, hue2:182, speed:0.56, distort:0.26 },
  { score:5, emoji:'😄', label:'Väldigt bra',    hue1:192, hue2:210, speed:0.80, distort:0.14 },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick');
  const active = hovered ?? selected ?? 2;
  const m = MOODS[active];

  const handleSave = () => { addMood(MOODS[selected].score, MOODS[selected].emoji, MOODS[selected].label, note); setStep('done'); };

  if (todayChecked && step!=='done') return <Done mood={MOODS[2]} title="Redan incheckad" sub="Kom tillbaka imorgon." setPage={setPage}/>;
  if (step==='done') return <Done mood={MOODS[selected]} title="Sparat" sub={MOODS[selected].label} setPage={setPage}/>;

  if (step==='note') return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, position:'relative', overflow:'hidden' }}>
      <div style={{ display:'flex', justifyContent:'space-between', padding:'22px 22px 0', position:'relative', zIndex:3 }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Check-in</span>
        <button onClick={()=>setStep('pick')} style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(17,16,16,0.35)', letterSpacing:'0.14em', textTransform:'uppercase' }}>← Ändra</button>
      </div>

      <div style={{ padding:'16px 20px 0', position:'relative', zIndex:3 }}>
        <div style={{ fontSize:'clamp(44px,12vw,72px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.85, color:'#111010', textTransform:'uppercase', marginBottom:4 }}>
          {MOODS[selected].label.split(' ')[0]}
        </div>
        <div style={{ fontSize:'clamp(30px,8vw,48px)', fontWeight:300, fontStyle:'italic', letterSpacing:'-0.03em', color:'rgba(17,16,16,0.28)', textTransform:'lowercase', lineHeight:1 }}>
          {MOODS[selected].label.split(' ').slice(1).join(' ')}
        </div>
      </div>

      <div style={{ position:'relative', zIndex:2, marginTop:'-20px', display:'flex', justifyContent:'flex-start', paddingLeft:'10%' }}>
        <MeshSphere size={220} speed={MOODS[selected].speed} distort={MOODS[selected].distort} hue1={MOODS[selected].hue1} hue2={MOODS[selected].hue2} key={selected} />
      </div>

      <div style={{ padding:'0 20px', position:'relative', zIndex:3, marginTop:'-20px' }}>
        <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:16 }} />
        <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
          placeholder="Valfri notering..."
          style={{ width:'100%', background:'rgba(17,16,16,0.04)', border:'1px solid rgba(17,16,16,0.08)', borderRadius:14, padding:'14px 16px', color:'#111010', fontSize:15, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7, marginBottom:12 }} />
        <button onClick={handleSave} style={{ width:'100%', padding:'14px', borderRadius:100, background:'#111010', color:'#f0ede8', fontSize:13, fontWeight:700, border:'none', boxShadow:'0 4px 20px rgba(0,0,0,0.12)' }}>Spara →</button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, overflow:'hidden', position:'relative' }}>
      <div style={{ display:'flex', justifyContent:'space-between', padding:'22px 22px 0', position:'relative', zIndex:3 }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Check-in</span>
      </div>

      {/* Big heading */}
      <div style={{ padding:'14px 20px 0', position:'relative', zIndex:3 }}>
        <div style={{ fontSize:'clamp(52px,14vw,86px)', fontWeight:900, letterSpacing:'-0.055em', lineHeight:0.84, color:'#111010', textTransform:'uppercase' }}>
          HUR<br/>MÅR DU?
        </div>
      </div>

      {/* Orb right-aligned, overlaps heading */}
      <div style={{ position:'relative', zIndex:2, marginTop:'-60px', display:'flex', justifyContent:'flex-end', paddingRight:'5%', pointerEvents:'none', transition:'all .5s' }}>
        <MeshSphere size={240} speed={m.speed} distort={m.distort} hue1={m.hue1} hue2={m.hue2} key={active} />
      </div>

      {/* Mood list */}
      <div style={{ padding:'0 20px', position:'relative', zIndex:3, marginTop:'-30px' }}>
        <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:12 }} />

        {MOODS.slice().reverse().map((mood, i) => {
          const idx = 4 - i;
          const isSel = selected === idx;
          const isHov = hovered === idx;
          return (
            <button key={mood.score}
              onMouseEnter={()=>setHovered(idx)} onMouseLeave={()=>setHovered(null)}
              onClick={()=>setSelected(idx)}
              style={{ width:'100%', display:'flex', alignItems:'center', gap:14, padding:'12px 14px', borderRadius:12, background:isSel?'rgba(17,16,16,0.07)':'transparent', border:`1px solid ${isSel?'rgba(17,16,16,0.14)':'transparent'}`, transition:'all .2s', marginBottom:4, transform:isHov&&!isSel?'translateX(4px)':'none' }}>
              <span style={{ fontSize:20 }}>{mood.emoji}</span>
              <span style={{ fontSize:15, fontWeight:isSel?700:300, color:isSel?'#111010':'rgba(17,16,16,0.55)', transition:'all .2s', flex:1, textAlign:'left' }}>{mood.label}</span>
              {(isSel||isHov) && <span style={{ fontSize:12, color:'rgba(17,16,16,0.25)' }}>→</span>}
            </button>
          );
        })}

        <div style={{ height:1, background:'rgba(17,16,16,0.08)', margin:'8px 0 14px' }} />
        <button onClick={()=>setStep('note')} disabled={selected===null}
          style={{ width:'100%', padding:'14px', borderRadius:100, background:selected!==null?'#111010':'rgba(17,16,16,0.07)', color:selected!==null?'#f0ede8':'rgba(17,16,16,0.22)', fontSize:13, fontWeight:700, border:'none', transition:'all .3s', boxShadow:selected!==null?'0 4px 20px rgba(0,0,0,0.12)':'none' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}

function Done({ mood, title, sub, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, display:'flex', flexDirection:'column', position:'relative', overflow:'hidden' }}>
      <div style={{ padding:'22px 22px 0' }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Spiral</span>
      </div>
      <div style={{ flex:1, display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'0 20px 0' }}>
        <div style={{ fontSize:'clamp(52px,14vw,86px)', fontWeight:900, letterSpacing:'-0.055em', lineHeight:0.84, color:'#111010', textTransform:'uppercase', marginBottom:'-30px', position:'relative', zIndex:3 }}>
          {title.toUpperCase()}
        </div>
        <div style={{ position:'relative', zIndex:2, display:'flex', justifyContent:'flex-end' }}>
          <MeshSphere size={240} speed={mood.speed} distort={mood.distort} hue1={mood.hue1} hue2={mood.hue2} />
        </div>
        <div style={{ position:'relative', zIndex:3, marginTop:'-20px' }}>
          <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:16 }} />
          <p style={{ fontSize:14, color:'rgba(17,16,16,0.45)', marginBottom:20, fontWeight:300 }}>{sub}</p>
          <div style={{ display:'flex', gap:8 }}>
            <button onClick={()=>setPage('history')} style={{ flex:1, padding:'13px', borderRadius:100, background:'#111010', color:'#f0ede8', fontSize:13, fontWeight:600, border:'none' }}>Historik</button>
            <button onClick={()=>setPage('home')} style={{ padding:'13px 18px', borderRadius:100, background:'rgba(17,16,16,0.06)', border:'1px solid rgba(17,16,16,0.1)', color:'rgba(17,16,16,0.5)', fontSize:13 }}>Hem</button>
          </div>
        </div>
      </div>
    </div>
  );
}
